# Selective Field Retrieval demo: push-down projection with access control.
RECORDS={"r1":{"id":"r1","title":"Solar Sails","body":"x"*5000,"secret":"classified","author":{"name":"J. Doe","email":"j@x.io"},"tags":["a","b","c","d"]}}
SCHEMA={"id":"str","title":"str","body":"str","secret":"str","author.name":"str","author.email":"str","tags":"list"}
DENIED={"secret"}
def project(rec_id,fields):
    rec=RECORDS[rec_id]; out={}
    for f in fields:
        if f in DENIED: out[f]="<redacted: not authorized>"; continue
        if f not in SCHEMA: raise ValueError("unknown field: "+f)
        if f=="*": out.update({k:v for k,v in rec.items() if k not in DENIED}); continue
        val=rec
        for part in f.split("."): val=val[part]
        out[f]=val
    return out
print(project("r1",["id","title","author.name"]))
print(project("r1",["secret","tags"]))

